#!/usr/bin/env bash
# slot-inventory.sh — in-VM orphans-equivalent inventory, baked into
# multica-slot-base and executed by the slot tool layer (E3) before/after
# release, mirroring the local slot `orphans` verb: after down/destroy,
# nothing of this slot survives. Read-only: it reports, never kills.
#
# Usage:
#   slot-inventory.sh --env <env-file> [--json]
# Env file (generated by the slot tool layer at acquire time):
#   SLOT_NAME, API_PORT, WEB_PORT, DESKTOP_PORT, MCP_PORT, WORKSPACE_ROOT
# Checks:
#   1. registered ports free (any listener = residue)
#   2. multica-shaped processes tied to this slot (cwd/args referencing
#      WORKSPACE_ROOT or SLOT_NAME, or a cmd/api build) = residue
#   3. git carriers under WORKSPACE_ROOT: report only (guard's domain)
# Exit codes: 0 clean · 1 residue found · 2 usage/environment error.
set -uo pipefail

usage() { printf 'usage: slot-inventory.sh --env <env-file> [--json]\n' >&2; exit 2; }

env_file=""; as_json=0
while [ $# -gt 0 ]; do
  case "$1" in
    --env) env_file=${2:-}; shift 2 ;;
    --json) as_json=1; shift ;;
    *) usage ;;
  esac
done
[ -n "$env_file" ] && [ -f "$env_file" ] || usage
# shellcheck disable=SC1090
. "$env_file"

registered_ports=""
for v in API_PORT WEB_PORT DESKTOP_PORT MCP_PORT; do
  [ -n "${!v:-}" ] && registered_ports="$registered_ports ${!v}"
done
workspace_root="${WORKSPACE_ROOT:-}"
slot_name="${SLOT_NAME:-}"

port_residues=()
proc_residues=()
carriers=0

# 1. listeners on registered ports (ss -tlnp; tolerate BusyBox/coreutils variance)
ss_out="$(ss -tlnp 2>/dev/null || true)"
while IFS= read -r line; do
  local_port="$(printf '%s' "$line" | sed -n 's/.*[:.]\([0-9]\{1,5\}\) [0-9.]*:[0-9*]* .*/\1/p')"
  [ -n "$local_port" ] || continue
  for rp in $registered_ports; do
    if [ "$local_port" = "$rp" ]; then
      port_residues+=("port $rp held by: $line")
    fi
  done
done <<EOF2
$ss_out
EOF2

# 2. multica-shaped processes tied to this slot
ps_out="$(ps -eo pid=,args= 2>/dev/null || true)"
while IFS= read -r line; do
  [ -n "$line" ] || continue
  pid="$(printf '%s' "$line" | awk '{print $1}')"
  args="$(printf '%s' "$line" | cut -c9-)"
  case "$args" in
    *"$workspace_root"*|*"multica"*) : ;;
    *) continue ;;
  esac
  # A multica match is only this slot's residue when it names our workspace
  # root, our slot name, or is a cmd/api build (the local audit's shape).
  case "$args" in
    *"$workspace_root"*|*"$slot_name"*|*cmd/api*|*multica-api*|*multica-web*|*multica*daemon*) ;;
    *) continue ;;
  esac
  [ -n "$workspace_root" ] || case "$args" in *cmd/api*) ;; *) continue ;; esac
  proc_residues+=("pid $pid: $args")
done <<EOF3
$ps_out
EOF3

# 3. git carriers under the workspace root (report only)
if [ -n "$workspace_root" ] && [ -d "$workspace_root" ]; then
  carriers="$(find "$workspace_root" -maxdepth 4 -name .git \( -type d -o -type f \) 2>/dev/null | wc -l | tr -d ' ')"
fi

residue=$(( ${#port_residues[@]} + ${#proc_residues[@]} ))
if [ "$as_json" = 1 ]; then
  printf '{"clean": %s, "port_residues": [' "$([ "$residue" = 0 ] && printf true || printf false)"
  first=1
  for r in "${port_residues[@]:-}"; do
    [ -n "$r" ] || continue
    [ "$first" = 1 ] || printf ', '
    printf '"%s"' "$(printf '%s' "$r" | sed 's/"/\\"/g')"
    first=0
  done
  printf '], "process_residues": ['
  first=1
  for r in "${proc_residues[@]:-}"; do
    [ -n "$r" ] || continue
    [ "$first" = 1 ] || printf ', '
    printf '"%s"' "$(printf '%s' "$r" | sed 's/"/\\"/g')"
    first=0
  done
  printf '], "git_carriers": %s}\n' "${carriers:-0}"
else
  for r in "${port_residues[@]:-}"; do [ -n "$r" ] && printf 'residue: %s\n' "$r"; done
  for r in "${proc_residues[@]:-}"; do [ -n "$r" ] && printf 'residue: %s\n' "$r"; done
  printf 'inventory: %s (git carriers under workspace: %s, report only)\n' \
    "$([ "$residue" = 0 ] && printf clean || printf DIRTY)" "${carriers:-0}"
fi
[ "$residue" = 0 ]
